import {FARMS,terrainHeight} from './world.js';

export function makeFarms(THREE,scene){
 const occluders=[],windows=[],lamps=[],rotors=[],groups=[];
 const boxGeo=new THREE.BoxGeometry(1,1,1),ballGeo=new THREE.SphereGeometry(1,32,24),wood=new THREE.MeshStandardMaterial({color:0x8d5d39,roughness:1}),dark=new THREE.MeshStandardMaterial({color:0x493c30,roughness:1}),stone=new THREE.MeshStandardMaterial({color:0xa6a18b,roughness:1});
 const paint=color=>new THREE.MeshStandardMaterial({color,roughness:.9});
 function mesh(parent,geo,mat,x,y,z,sx=1,sy=1,sz=1){const object=new THREE.Mesh(geo,mat);object.position.set(x,y,z);object.scale.set(sx,sy,sz);object.castShadow=true;object.receiveShadow=true;parent.add(object);occluders.push(object);return object;}
 function box(parent,mat,x,y,z,sx,sy,sz){return mesh(parent,boxGeo,mat,x,y,z,sx,sy,sz);}
 function house(root,width,depth,height,wallColor,roofColor){const wall=paint(wallColor),roofMat=paint(roofColor);box(root,stone,0,.25,0,width+.4,.5,depth+.4);box(root,wall,0,height/2+.4,0,width,height,depth);const shape=new THREE.Shape();shape.moveTo(-width/2-.5,0);shape.lineTo(width/2+.5,0);shape.lineTo(0,2.1);shape.closePath();mesh(root,new THREE.ExtrudeGeometry(shape,{depth:depth+1,bevelEnabled:false}),roofMat,0,height+.4,-depth/2-.5);box(root,wood,0,1.3,depth/2+.03,1.15,2,.12);
  const glow=paint(0xffcf7d);glow.emissive=new THREE.Color(0xffab49);windows.push(glow);for(const x of [-width*.3,width*.3]){box(root,wood,x,2,depth/2+.06,1.2,1.2,.14);box(root,glow,x,2,depth/2+.15,.92,.92,.06);box(root,wood,x,2,depth/2+.2,.07,1,.07);box(root,wood,x,2,depth/2+.2,1,.07,.07);}box(root,stone,width*.3,height+1.2,-depth*.22,.65,2,.65);
  const lamp=new THREE.PointLight(0xffb65c,0,14,2);lamp.position.set(0,2.9,depth/2+1);root.add(lamp);lamps.push(lamp);
 }
 function fence(root){for(const z of [-13,13])for(let x=-15;x<=15;x+=3){if(z===13&&Math.abs(x)<4)continue;box(root,wood,x,.65,z,.14,1.3,.14);if(x<15&&!(z===13&&x===-6)){box(root,wood,x+1.5,.45,z,3,.1,.1);box(root,wood,x+1.5,.95,z,3,.1,.1);}}}
 function cart(root,x,z,load){const group=new THREE.Group();group.position.set(x,.65,z);root.add(group);box(group,wood,0,0,0,1.65,.15,2.5);for(const side of [-1,1])for(let tier=0;tier<3;tier++)box(group,wood,side*.85,.2+tier*.23,0,.09,.14,2.6);box(group,wood,0,.45,-1.25,1.7,.7,.09);for(const zz of [-.85,.85])for(const side of [-1,1]){const wheel=mesh(group,new THREE.TorusGeometry(.5,.06,12,64),dark,side*1.03,-.08,zz);wheel.rotation.y=Math.PI/2;for(let k=0;k<6;k++){const spoke=box(group,wood,side*1.03,-.08,zz,.055,.92,.055);spoke.rotation.x=k*Math.PI/3;}}for(const side of [-1,1])box(group,wood,side*.48,-.02,2.1,.07,.07,2.3);for(let i=0;i<8;i++)mesh(group,ballGeo,paint(load),((i%2)-.5)*.65,.35+Math.floor(i/4)*.38,(Math.floor(i/2)%2-.5)*1.1,.32,.3,.36);return group;}
 for(const farm of FARMS){const root=new THREE.Group();root.position.set(farm.x,terrainHeight(farm.x,farm.z)+.03,farm.z);scene.add(root);groups.push(root);fence(root);
  if(farm.id==='orchard'){house(root,6,5,3,0xf1d7a5,0xb95a3a);for(let i=0;i<6;i++){const x=-9+(i%2)*4,z=-8+Math.floor(i/2)*6;mesh(root,new THREE.CylinderGeometry(.16,.24,3.4,24),wood,x,1.7,z);mesh(root,ballGeo,paint(0x71a43a),x,3.5,z,1.8,1.5,1.8);for(let j=0;j<7;j++){const a=j*Math.PI*2/7;mesh(root,ballGeo,paint(j%2?0xf2b643:0xe36843),x+Math.cos(a)*1.45,3.4+Math.sin(j*3)*.6,z+Math.sin(a)*1.45,.14,.16,.14);}}cart(root,8,7,0xe57539);}
  if(farm.id==='lavender'){house(root,5.5,5,2.9,0xe9e1c9,0x74648f);const blooms=new THREE.InstancedMesh(ballGeo,paint(0xa27fda),600),dummy=new THREE.Object3D();for(let i=0;i<600;i++){dummy.position.set(5+(i%8)*.8,.4+Math.sin(i)*.07,-10+Math.floor(i/8)*.24);dummy.scale.set(.16,.32,.16);dummy.updateMatrix();blooms.setMatrixAt(i,dummy.matrix);}root.add(blooms);mesh(root,new THREE.CylinderGeometry(.8,.85,.7,24),stone,-7,.35,7);cart(root,-8,-8,0xa68acb);}
  if(farm.id==='wheat'){house(root,7,6,4,0xb65c45,0x596f6b);const mill=new THREE.Group();mill.position.set(-9,0,-5);root.add(mill);mesh(mill,new THREE.CylinderGeometry(1.1,1.5,6.8,24),paint(0xe8d7ae),0,3.4,0);mesh(mill,new THREE.ConeGeometry(1.6,2,24),paint(0x735947),0,7.6,0);const rotor=new THREE.Group();rotor.position.set(0,5.8,1.2);mill.add(rotor);for(let k=0;k<4;k++){const arm=new THREE.Group();arm.rotation.z=k*Math.PI/2;rotor.add(arm);box(arm,wood,0,1.6,0,.1,3.2,.1);box(arm,paint(0xede4be),.35,2,0,.65,1.8,.06);}rotors.push(rotor);const wheat=new THREE.InstancedMesh(new THREE.CylinderGeometry(.025,.035,.8,24),paint(0xe5bd55),700),dummy=new THREE.Object3D();for(let i=0;i<700;i++){dummy.position.set(5+(i%14)*.4,.4,-10+Math.floor(i/14)*.37);dummy.rotation.z=Math.sin(i)*.08;dummy.updateMatrix();wheat.setMatrixAt(i,dummy.matrix);}root.add(wheat);cart(root,1,9,0xd8b85d);for(let i=0;i<4;i++){const bale=mesh(root,new THREE.CylinderGeometry(.65,.65,1.4,24),paint(0xd4b86a),-6+i*1.5,.65,9);bale.rotation.z=Math.PI/2;}}
 }
 const roadside=new THREE.Group();roadside.position.set(68,terrainHeight(68,25),25);roadside.rotation.y=.5;scene.add(roadside);cart(roadside,0,0,0xd0ab67);groups.push(roadside);
 return{occluders,update(time,night){for(const rotor of rotors)rotor.rotation.z=time*.13;for(const material of windows)material.emissiveIntensity=.08+night*1.8;for(const lamp of lamps)lamp.intensity=night*24;},cull(camera){for(const group of groups)group.visible=camera.position.distanceTo(group.position)<500;}};
}
